const correlationId = crypto.randomUUID();
const { queue: replyTo } = await ch.assertQueue('', { exclusive: true });
ch.consume(replyTo, (msg) => {
  if (msg.properties.correlationId === correlationId) resolve(msg.content.toString());
}, { noAck: true });
ch.sendToQueue('rpc_queue', Buffer.from('10'), { replyTo, correlationId });

// service
ch.sendToQueue(msg.properties.replyTo, Buffer.from(fib(10).toString()),
  { correlationId: msg.properties.correlationId });
